{
  "items": [
    {
      "name": "AddMonoidAlgebra.sup_support_pow_le",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {B : Type u_5} [inst : SemilatticeSup B] [inst_1 : OrderBot B] [inst_2 : Semiring R]\n  [inst_3 : AddMonoid A] [inst_4 : AddMonoid B] [AddLeftMono B] [AddRightMono B] {degb : A → B},\n  degb 0 ≤ 0 →\n    (∀ (a b : A), degb (a + b) ≤ degb a + degb b) →\n      ∀ (n : ℕ) (f : AddMonoidAlgebra R A), (f ^ n).support.sup degb ≤ n • f.support.sup degb"
    },
    {
      "name": "Polynomial.support",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → Polynomial R → Finset ℕ"
    },
    {
      "name": "IsPoly.below.proj",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "constructor",
      "type": "∀ {α : Type u_1} {motive : (a : (α → ℕ) → ℤ) → IsPoly a → Prop} (i : α), IsPoly.below ⋯"
    },
    {
      "name": "MvPolynomial.support",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset (σ →₀ ℕ)"
    },
    {
      "name": "MvPolynomial.degreeOf_eq_sup",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (n : σ) (f : MvPolynomial σ R),\n  MvPolynomial.degreeOf n f = f.support.sup fun m => m n"
    }
  ]
}
